    used_values = set()

    for i in range(n):
        if arr[i] != -1:
            used_values.add(arr[i])
        else:
            missing_positions.append(i + 1)  # 1-indexed

    # Find missing values
    missing_values = []
    for i in range(1, n + 1):
        if i not in used_values:
            missing_values.append(i)

    k = len(missing_positions)

    # Count m: positions where position index == value index
    m = 0
    for pos in missing_positions:
        if pos in missing_values:
            m += 1

    # Precompute factorials
    fact = [1] * (k + 1)
    for i in range(2, k + 1):
        fact[i] = (fact[i - 1] * i) % MOD

    # Precompute inverse factorials
    inv_fact = [1] * (k + 1)
    inv_fact[k] = pow(fact[k], MOD - 2, MOD)
    for i in range(k - 1, -1, -1):
        inv_fact[i] = (inv_fact[i + 1] * (i + 1)) % MOD

    # C(n, r) = n! / (r! * (n-r)!)
    def combination(n, r):
        if r < 0 or r > n:
            return 0
        return fact[n] * inv_fact[r] % MOD * inv_fact[n - r] % MOD

    # Inclusion-exclusion principle: sum_{j=0}^{m} (-1)^j * C(m, j) * (k - j)!
    ans = 0
    for j in range(m + 1):
        ways = combination(m, j) * fact[k - j] % MOD
        if j % 2 == 1:
            ans = (ans - ways + MOD) % MOD
        else:
            ans = (ans + ways) % MOD

    return str(ans) + '\n'
