def solution(input_str):
    """
    Count geometric progressions of length n where all elements are in [l, r].
    """
    n, l, r = map(int, input_str.split())

    if n == 1:
        # All single elements are valid
        return str(r - l + 1) + "\n"

    if n == 2:
        # All ordered pairs of distinct elements in [l, r]
        M = r - l + 1
        return str(M * (M - 1)) + "\n"

    # For n >= 3, count valid geometric progressions
    count = 0

    for first in range(l, r + 1):
        # Try increasing ratios
        for ratio in range(1, r) + 1):
            if first * (ratio ** (n-1)) > r:
                break
            # Check if geometric progression stays in bounds
            terms = [first * (ratio ** i) for i in range(n)]
            if len(set(terms)) == n and len(terms) == n:
                count += 1

        # Try ratios < 1 (equivalent to reciprocal of ratios > 1)
        for ratio in range(1, r):
            if first // (ratio ** (n-1)) < l:
                continue
            terms = [first // (ratio ** i) for i in range(n)]
            if len(set(terms)) == n:
                count += 1

    return str(count) + "\n"
