def fibonacci(n, cached=False):
    """
    Given n, find the number of ways to decompose it into Fibonacci numbers.
    F1=1, F2=2, F3=3, F4=5, ...
    """
    # Precompute Fibonacci numbers
    fibs = [1, 2]
    while fibs[-1] < 10**18:
        fibs.append(fibs[-1] + fibs[-2])

    # Count for n = 0
    if n == 0:
        return 1

    # Find position and count
    def count_decompositions(target):
        memo = {}

        def dp(rem, index):
            if rem == 0:
                return 1
            if rem < 0:
                return 0
            if rem in memo:
                return memo[rem]

            count = 0
            # Use Fibonacci numbers from index downwards
            for i in range(index, 0, -1):
                if fibs[i] <= rem:
                    count += dp(rem - fibs[i], max(0, i-1))

            memo[rem] = count
            return count

        return dp(target, len(fibs) - 1)

    return count_decompositions(n)
