    lines = input_str.strip().split('\n')
    n, d = map(int, lines[0].split())
    circles = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        x, y, r = map(float, parts)
        circles.append((x, y, r))

    events = []
    for x, y, r in circles:
        L = math.sqrt(x*x + y*y)
        min_dist = abs(L - r)
        max_dist = L + r

        for k in range(1, 1000000):
            R = k * d
            if R > max_dist + 1e-9:
                break

            if R >= min_dist - 1e-9 and L > 1e-9:
                numerator = R*R + L*L - r*r
                denominator = 2 * R * L

                cos_val = numerator / denominator
                cos_val = max(-1.0, min(1.0, cos_val))

                gamma = math.atan2(y, x)
                angle_range = math.acos(cos_val)

                # Normalize angles to [-pi, pi]
                events.append((gamma - angle_range, 1))
                events.append((gamma + angle_range, -1))

    events.sort()

    max_points = 0
    current = 0
    num_events = len(events)

    for i in range(num_events):
        current += events[i][1]
        max_points = max(max_points, current)

